import { posix } from "node:path";
import { compareCodePoints } from "../../domain/canonicalOrdering.js";
import { completeApplicationCoverage, partialApplicationCoverage, } from "../../domain/javascript/javascriptApplicationEvidenceSchemas.js";
import { semanticCoverageResourceLimits } from "../../domain/javascript/javascriptSemanticCoverage.js";
import { SEMANTIC_EXPRESSION_DEPTH_LIMIT, SEMANTIC_PRIMITIVE_CANDIDATE_LIMIT, SEMANTIC_PRIMITIVE_JSON_BYTES_LIMIT, semanticResourceLimitReason, } from "../../domain/javascript/javascriptSemanticResourceLimits.js";
import { addAstContainsEdge, artifactLocalIdentity, } from "./JavaScriptArtifactGraphContext.js";
import { astObservationEvidence, staticInferenceEvidence, } from "./JavaScriptArtifactGraphEvidence.js";
import { resolveArtifactPathByContext, } from "./JavaScriptArtifactPathResolution.js";
import { projectJavaScriptExportReturnShapes } from "./JavaScriptReturnShapeProjection.js";
/** Create one path-scoped source-module identity for every analyzed source file. */
export const addJavaScriptSourceModules = (context) => {
    for (const analyzed of context.analysis.files) {
        const { file, semantic } = analyzed;
        const asset = context.assetNodes.get(file.path);
        const program = semantic?.ir.scopes.find(({ kind }) => kind === "program");
        if (asset === undefined || semantic === null || program === undefined)
            continue;
        const exports = semantic.ir.moduleLinks
            .flatMap(({ exportedName }) => exportedName === null ? [] : [exportedName])
            .sort(compareCodePoints);
        const retainedExports = [...new Set(exports)];
        const source = context.accumulator.addNode({
            kind: "javascript-module",
            identity: artifactLocalIdentity(file.sha256, "source-module", `${file.container_sha256}:${file.path}`),
            observations: [
                {
                    label: file.path,
                    properties: {
                        semantic_role: "source-module",
                        path: file.path,
                        container_sha256: file.container_sha256,
                        logical_module_key: file.path,
                        module_format: moduleFormat(file.path, semantic.ir),
                        import_relationships: semantic.ir.moduleLinks.filter(({ kind }) => kind === "import" || kind === "require").length,
                        export_relationships: exports.length,
                        export_names: retainedExports,
                        omitted_export_names: 0,
                    },
                    evidence: astObservationEvidence({
                        sha256: file.sha256,
                        path: file.path,
                        range: program.location,
                        operation: "recover-source-module",
                        coverage: semanticCoverage(semantic),
                        limitations: semantic.ir.limitations,
                    }),
                },
            ],
        });
        context.sourceModuleNodes.set(file.path, source);
        addAstContainsEdge(context, {
            source: asset,
            target: source,
            file,
            range: program.location,
            coverage: semanticCoverage(semantic),
            properties: { logical_module_key: file.path },
        });
    }
};
/** Compose bounded CommonJS and ESM binding relationships across artifact files. */
export const addJavaScriptModuleRelationships = (context) => {
    const omissions = { selfImports: 0 };
    for (const analyzed of context.analysis.files) {
        const { file, semantic } = analyzed;
        const source = context.sourceModuleNodes.get(file.path);
        if (semantic === null || source === undefined)
            continue;
        for (const link of semantic.ir.moduleLinks) {
            const input = { context, file, semantic, source, link };
            if (isExportLink(link))
                addExportRelationship(input, omissions);
            else if (link.specifier !== null)
                addImportRelationship(input, source, omissions, {
                    specifier: link.specifier,
                    importedPath: link.importedName === null ? [] : [link.importedName],
                });
        }
    }
    return omissions;
};
const addExportRelationship = (input, omissions) => {
    const { context, file, semantic, source, link } = input;
    if (link.exportedName === null)
        return;
    const baseCoverage = semanticCoverage(semantic);
    const returnShapes = projectJavaScriptExportReturnShapes({
        ir: semantic.ir,
        link,
        modulePath: file.path,
        baseCoverage,
    });
    const exported = context.accumulator.addNode({
        kind: "javascript-module",
        identity: artifactLocalIdentity(file.sha256, "module-export", `${file.container_sha256}:${file.path}:${link.exportedName}`),
        observations: [
            {
                label: `${file.path}:${link.exportedName}`,
                properties: {
                    semantic_role: "export-binding",
                    module_path: file.path,
                    relationship_kind: link.kind,
                    exported_name: link.exportedName,
                    local_name: link.localName,
                    imported_name: link.importedName,
                    declared_specifier: link.specifier,
                },
                evidence: astObservationEvidence({
                    sha256: file.sha256,
                    path: file.path,
                    range: link.location,
                    operation: "recover-module-export",
                    coverage: baseCoverage,
                    limitations: semantic.ir.limitations,
                }),
            },
            ...(returnShapes === null
                ? []
                : [
                    {
                        label: `${file.path}:${link.exportedName}:return-shapes`,
                        properties: returnShapes.properties,
                        evidence: staticInferenceEvidence({
                            sha256: file.sha256,
                            path: file.path,
                            range: returnShapes.range,
                            operation: "recover-export-return-shapes",
                            coverage: returnShapes.coverage,
                            limitations: returnShapes.limitations,
                        }),
                    },
                ]),
        ],
    });
    context.accumulator.addEdge({
        source_node_id: source.node_id,
        target_node_id: exported.node_id,
        relation: "exposes",
        properties: relationshipProperties(link, null),
        evidence: relationshipEvidence(input, "expose-module-export", []),
    });
    const origin = moduleOriginForExport(semantic.ir, link);
    if (origin !== null)
        addImportRelationship(input, exported, omissions, origin);
};
const addImportRelationship = (input, source, omissions, origin) => {
    const target = resolveModuleTarget(input, origin.specifier);
    // A specifier that resolves back to the importing module itself (a literal
    // self-import, self-require, or artifact-confined path alias)
    // cannot become an edge: the application graph forbids self-referential
    // edges, and emitting one fails result validation for the whole analysis.
    if (target.node.node_id === source.node_id) {
        omissions.selfImports += 1;
        return;
    }
    input.context.accumulator.addEdge({
        source_node_id: source.node_id,
        target_node_id: target.node.node_id,
        relation: "imports",
        properties: relationshipProperties(input.link, target, origin),
        evidence: relationshipEvidence(input, "resolve-semantic-module-relationship", target.limitations, target.status === "resolved"
            ? "high"
            : target.status === "external"
                ? "medium"
                : "low"),
    });
};
const resolveModuleTarget = (input, specifier) => {
    const resolution = resolveArtifactPathByContext({
        declaredPath: specifier,
        sourcePath: input.file.path,
        context: "module-specifier",
        files: input.context.filesByPath,
        moduleKind: input.link.kind === "require" || input.link.kind === "commonjs-export"
            ? "require"
            : "import",
    });
    if (resolution.resolution_status !== "resolved")
        return {
            node: unresolvedModuleNode(input, specifier, resolution.resolution_status),
            path: null,
            file: null,
            status: resolution.resolution_status,
            limitations: resolution.limitations,
        };
    const path = resolution.resolved_path;
    const file = input.context.filesByPath.get(path);
    const node = input.context.sourceModuleNodes.get(path) ??
        input.context.fileNodes.get(path);
    if (file === undefined || node === undefined)
        throw new TypeError(`Resolved artifact path ${path} is absent from its graph context.`);
    return {
        node,
        path,
        file,
        status: "resolved",
        limitations: resolution.limitations,
    };
};
const unresolvedModuleNode = (input, specifier, status) => input.context.accumulator.addNode({
    kind: "javascript-module",
    identity: artifactLocalIdentity(input.file.sha256, "unresolved-semantic-module", `${status}:${specifier}`),
    observations: [
        {
            label: specifier,
            properties: {
                semantic_role: "module-reference",
                declared_specifier: specifier,
                resolution_status: status,
            },
            evidence: staticInferenceEvidence({
                sha256: input.file.sha256,
                path: input.file.path,
                range: input.link.location,
                operation: "retain-unresolved-semantic-module",
                coverage: semanticCoverage(input.semantic),
                confidence: "low",
                limitations: input.semantic.ir.limitations,
            }),
        },
    ],
});
const moduleOriginForExport = (ir, link) => {
    if (link.specifier !== null)
        return {
            specifier: link.specifier,
            importedPath: link.importedName === null ? [] : [link.importedName],
        };
    if (link.localName === null)
        return null;
    const program = ir.scopes.find(({ kind }) => kind === "program");
    const binding = ir.bindings.find(({ name, scopeId }) => name === link.localName && scopeId === program?.scopeId);
    return binding?.provenance.status === "module" &&
        binding.provenance.origins.length === 1
        ? (binding.provenance.origins[0] ?? null)
        : null;
};
const relationshipProperties = (link, target, origin) => ({
    module_link_kind: link.kind,
    specifier: origin?.specifier ?? link.specifier,
    imported_name: origin?.importedPath.at(-1) ?? link.importedName,
    imported_path: origin?.importedPath ?? [],
    local_name: link.localName,
    exported_name: link.exportedName,
    resolved_path: target?.path ?? null,
    resolution_status: target?.status ?? null,
    target_file_kind: target?.file?.kind ?? null,
    target_json_status: target?.file?.kind === "json" ? jsonStatus(target.file) : null,
});
const relationshipEvidence = (input, operation, limitations, confidence = "high") => staticInferenceEvidence({
    sha256: input.file.sha256,
    path: input.file.path,
    range: input.link.location,
    operation,
    coverage: semanticCoverage(input.semantic),
    confidence,
    limitations: [
        ...input.semantic.ir.limitations,
        ...semanticCoverageResourceLimits(input.semantic.ir.coverage).map(semanticResourceLimitReason),
        ...limitations,
    ],
});
const semanticCoverage = (semantic) => {
    const resourceLimits = semanticCoverageResourceLimits(semantic.ir.coverage);
    if (semantic.ir.coverage.status === "complete" && resourceLimits.length === 0)
        return completeApplicationCoverage();
    return partialApplicationCoverage(resourceLimits.map((resourceLimit) => ({
        name: `javascript_semantic_${resourceLimit.replaceAll("-", "_")}`,
        value: resourceLimit === "primitive-candidates"
            ? SEMANTIC_PRIMITIVE_CANDIDATE_LIMIT
            : resourceLimit === "primitive-bytes"
                ? SEMANTIC_PRIMITIVE_JSON_BYTES_LIMIT
                : SEMANTIC_EXPRESSION_DEPTH_LIMIT,
        unit: resourceLimit === "expression-depth"
            ? "depth"
            : resourceLimit === "primitive-bytes"
                ? "bytes"
                : "items",
    })), semantic.ir.coverage.omittedCount);
};
const moduleFormat = (path, ir) => {
    const extension = posix.extname(path).toLowerCase();
    if (extension === ".mjs")
        return "esm";
    if (extension === ".cjs")
        return "commonjs";
    const esm = ir.moduleLinks.some(({ kind }) => ["import", "export", "re-export"].includes(kind));
    const commonJs = ir.moduleLinks.some(({ kind }) => ["require", "commonjs-export"].includes(kind));
    return esm && commonJs
        ? "mixed"
        : esm
            ? "esm"
            : commonJs
                ? "commonjs"
                : "unknown";
};
const jsonStatus = (file) => {
    if (!file.text.included)
        return "unavailable";
    try {
        JSON.parse(file.text.value);
        return "included";
    }
    catch (cause) {
        // Invalid JSON is classified without further detail.
        void cause;
        return "invalid";
    }
};
const isExportLink = (link) => link.kind === "export" ||
    link.kind === "re-export" ||
    link.kind === "commonjs-export";
